try {
    String nextID = ((PegaDatabase) tools.getDatabase()).getUniqueID(tools.getParamValue("IDPrefix"), tools.getParamValue("IDSuffix"));
    myStepPage.putString(".pyID", nextID);
} catch (DatabaseException ex) {
  myStepPage.addLocalizedMessage("UnableToObtainUniqueId\t"+ex.getMessage(),"pyMessageLabel");
    nextBlock = "***";
} catch (PRAppRuntimeException pre) {
    if (!pre.getRuleSetName().equals("Pega-ProCom")) {
        // We only catch Pega-ProCom PRAppRuntimeExceptions
        throw pre;
    }
    myStepPage.addLocalizedMessage("UnableToObtainUniqueId\t"+pre.getMessage(),"pyMessageLabel");
    nextBlock = "***";		
}
